const s = $('Start').first().json;
const ids = [...new Set([s.file_id, s.more_file_ids].join(',').split(/[^A-Za-z0-9_-]+/).filter((x) => x && !/^(none|null|undefined|empty)$/i.test(x)))];
const item = (json) => ({ json, pairedItem: { item: 0 } });
if (ids.length > 10) return [item({ file_id: '', error: 'More than 10 files in one call - call this tool in several groups of at most 10 files.' })];
return ids.length ? ids.map((file_id) => item({ file_id })) : [item({ file_id: '' })];

const list = $('List files').all().map((i) => i.json);
const got = $input.all().map((i) => i.json);
const out = (json) => [{ json, pairedItem: { item: 0 } }];
const no = (error, mime, failed) => out({ ok: false, error, mime: mime || '', failed_file_id: failed || '', file_count: list.length, file_ids: [] });
if (list[0].error) return no(list[0].error);
if (got.length !== list.length) return no('Only ' + got.length + ' of ' + list.length + ' files could be fetched - ask the user to send them again.');
const bad = got.findIndex((f) => !f.ok);
if (bad >= 0) {
  const others = list.length > 1 ? 'File ' + list[bad].file_id + ': ' : '';
  const next = list.length > 1 ? ' Nothing was read - call this tool again without this file_id.' : '';
  return no(others + got[bad].error + next, got[bad].mime, list[bad].file_id);
}
if (got.reduce((sum, f) => sum + String(f.b64 || '').length, 0) > 30 * 1024 * 1024) return no('These files are too large together - call this tool in smaller groups of files.');
return out({ ok: true, error: '', mime: '', failed_file_id: '', file_count: list.length, file_ids: list.map((f) => f.file_id) });

const anthropicText = (r) => {
  if (!r || !Array.isArray(r.content)) {
    const m = (r && r.error && (r.error.message || r.error.type || r.error.description)) || 'no response';
    return { ok: false, error: String(m).slice(0, 200) };
  }
  if (r.stop_reason === 'max_tokens') return { ok: false, error: 'answer truncated (max_tokens)' };
  if (r.stop_reason === 'refusal') return { ok: false, error: 'model declined the request' };
  if (r.stop_reason === 'pause_turn') return { ok: false, error: 'web search did not finish (pause_turn)' };
  const text = r.content.filter(b => b && b.type === 'text' && b.text).map(b => b.text).join('').trim();
  if (!text) return { ok: false, error: 'empty answer' };
  return { ok: true, text };
};
const stripFences = (t) => String(t).replace(/^\s*```[a-z]*\s*/i, '').replace(/\s*```\s*$/, '');const r = $input.first().json;
const fail = (code, m) => [{ json: { ok: false, code, error: m } }];
const res = anthropicText(r);
if (!res.ok) return fail('unreadable', 'The statement could not be read (' + res.error + ') - ask the user for the PDF from online banking or a sharper photo.');
let s;
try { s = JSON.parse(stripFences(res.text)); } catch (e) { return fail('unreadable', 'The statement could not be read - ask the user for the PDF from online banking.'); }
// Mehrere Dateien, die nicht EIN Auszug sind -> Gruppen an den Agenten (Datei ohne Gruppe = eigene Gruppe), keine Karte.
const ids = $('Collect files').first().json.file_ids;
if (ids.length > 1) {
  const seen = new Set();
  const groups = (s && Array.isArray(s.groups) ? s.groups : []).map((g) => (Array.isArray(g) ? g : []).filter((n) => Number.isInteger(n) && n >= 1 && n <= ids.length && !seen.has(n) && seen.add(n)).map((n) => ids[n - 1])).filter((g) => g.length);
  ids.forEach((id, i) => { if (!seen.has(i + 1)) groups.push([id]); });
  if (groups.length > 1) return [{ json: { ok: false, code: 'several_documents', groups, error: 'These files are not one statement of one account - nothing was booked. Call this tool once per entry of groups, one after the other: file_id = the first id of the group, more_file_ids = its other ids.' } }];
}
if (!s || s.is_statement !== true) return fail('not_a_statement', 'This is not an account statement with opening and closing balance. A depot statement, insurance or pension letter goes to tool_extract_finance_document; a plain transaction list cannot be checked against balances - ask for the monthly statement PDF.');
const txt = (v) => (typeof v === 'string' && v.trim() !== '') ? v.trim() : null;
const lines = (Array.isArray(s.lines) ? s.lines : []).map((l) => ({
  date: txt(l.date), amount: Number(l.amount), counterparty: txt(l.counterparty), counterparty_iban: txt(l.counterparty_iban),
  creditor_id: txt(l.creditor_id), mandate_ref: txt(l.mandate_ref), purpose: txt(l.purpose),
  recurring_kind: txt(l.recurring_kind), series: txt(l.series), rhythm_hint: txt(l.rhythm_hint) }));
return [{ json: { ok: true, account_number: txt(s.account_number), account_holder: txt(s.account_holder), currency: txt(s.currency), period_start: txt(s.period_start),
  period_end: txt(s.period_end), opening_balance: Number(s.opening_balance), closing_balance: Number(s.closing_balance),
  lines, line_count: lines.length } }];
